#define ZB_ACCEL_ERR_STATUS_STICKY_ACCESS ZB_ACCEL_ACCESS_W1C
#define ZB_ACCEL_ERR_STATUS_IS_WRITE_SHIFT 1u
#define ZB_ACCEL_ERR_STATUS_IS_WRITE_WIDTH 1u
#define ZB_ACCEL_ERR_STATUS_IS_WRITE_MASK 0x00000002u
#define ZB_ACCEL_ERR_STATUS_IS_WRITE_RESET 0x0u
#define ZB_ACCEL_ERR_STATUS_IS_WRITE_ACCESS ZB_ACCEL_ACCESS_RO
#define ZB_ACCEL_ERR_STATUS_COUNT_SHIFT 8u
#define ZB_ACCEL_ERR_STATUS_COUNT_WIDTH 8u
#define ZB_ACCEL_ERR_STATUS_COUNT_MASK 0x0000ff00u
#define ZB_ACCEL_ERR_STATUS_COUNT_RESET 0x0u
#define ZB_ACCEL_ERR_STATUS_COUNT_ACCESS ZB_ACCEL_ACCESS_RO

/* field helpers: ZB_ACCEL_GET(R, F, word) extracts a field; ZB_ACCEL_PUT(R, F, v) places v in a field */
#define ZB_ACCEL_GET(R, F, word) (((uint32_t)(word) & ZB_ACCEL_##R##_##F##_MASK) >> ZB_ACCEL_##R##_##F##_SHIFT)
#define ZB_ACCEL_PUT(R, F, v) (((uint32_t)(v) << ZB_ACCEL_##R##_##F##_SHIFT) & ZB_ACCEL_##R##_##F##_MASK)

#ifndef ZB_ACCEL_IO_READ32
#define ZB_ACCEL_IO_READ32(addr) (*(volatile uint32_t *)(uintptr_t)(addr))
#endif
#ifndef ZB_ACCEL_IO_WRITE32
#define ZB_ACCEL_IO_WRITE32(addr, v) (*(volatile uint32_t *)(uintptr_t)(addr) = (uint32_t)(v))
#endif

static inline uint32_t zb_accel_read(uintptr_t base, uint32_t offset)
{ return ZB_ACCEL_IO_READ32(base + offset); }
static inline void zb_accel_write(uintptr_t base, uint32_t offset, uint32_t value)
{ ZB_ACCEL_IO_WRITE32(base + offset, value); }

#endif /* ZB_ACCEL_REGS_H */
